import json
import math
import random

from air_quality.health import (
    robust_policy_change_summary,
    robust_policy_joint,
    robust_policy_lineage,
)

kind_pos = {"split": 0, "merge": 1, "merge_split": 2}


def oracle(args, S, J, L):
    assert list(S.keys()) == ["budgets", "z", "regions", "consistent", "conflicts"]
    assert S["budgets"] == J["budgets"] and S["z"] == J["z"]
    assert S["budgets"] is not J["budgets"]
    json.dumps(S)

    node_region = {}
    for axis in ("budget", "z"):
        for node in L["axes"][axis]["nodes"]:
            node_region[(axis, node[0])] = node[5]

    counts = {}
    rank_terms, level_terms = {}, {}
    for ei, (axis, pair, kind, frm, to, ov) in enumerate(J["branches"]):
        regs = {node_region[(axis, n)] for n in list(frm) + list(to)}
        slot = (0 if axis == "budget" else 3) + kind_pos[kind]
        for r in regs:
            counts.setdefault(r, {}).setdefault(slot, set()).add(ei)

    for ch in J["adjacency_changes"]:
        axis, e1, e2, action, small, large, rd, ld = ch
        for r in (small, large):
            rank_terms.setdefault(r, []).extend(abs(v) for v in rd)
            level_terms.setdefault(r, []).extend(abs(v) for v in ld)

    all_regions = sorted(
        {node[5] for a in ("budget", "z") for node in L["axes"][a]["nodes"]}
    )
    expected = []
    for r in all_regions:
        B = [0] * 6
        for slot, evs in counts.get(r, {}).items():
            B[slot] = len(evs)
        expected.append(
            [r, B, math.fsum(rank_terms.get(r, [])), math.fsum(level_terms.get(r, []))]
        )
    assert S["regions"] == expected

    by_pair = {}
    for pos, ch in enumerate(J["adjacency_changes"]):
        axis, e1, e2, action, small, large, rd, ld = ch
        by_pair.setdefault((small, large), {}).setdefault(axis, []).append(
            (pos, [action, list(rd), list(ld)])
        )
    exp_cons, exp_conf = [], []
    for (small, large), per in sorted(by_pair.items()):
        if "budget" not in per or "z" not in per:
            continue
        bl = [e for _, e in per["budget"]]
        zl = [e for _, e in per["z"]]
        if bl == zl:
            exp_cons.append([small, large])
        else:
            exp_conf.append(
                [small, large, [p for p, _ in per["budget"]], [p for p, _ in per["z"]]]
            )
    assert S["consistent"] == exp_cons, (S["consistent"], exp_cons)
    assert S["conflicts"] == exp_conf, (S["conflicts"], exp_conf)


def make_case(seed):
    rng = random.Random(seed)
    K = rng.choice([2, 3, 4])
    N = rng.choice([1, 2, 3])
    H = [[rng.uniform(-1, 8) for _ in range(N)] for _ in range(K)]
    W = [[rng.uniform(0.0, 2.0) for _ in range(N)] for _ in range(K)]
    thresholds = [1.0, 2.5, 4.0]
    quantiles = rng.choice([[0.5], [0.4, 0.8], [0.25, 0.5, 0.75]])
    P = rng.randint(1, 3)
    policies = []
    for _ in range(P):
        d1 = 1
        d2 = rng.randint(2, min(2, K))
        d3 = rng.randint(d2 + 1, K) if d2 < K else K
        policies.append([rng.randint(0, 3), rng.randint(1, N), d1, d2, d3])
    options = []
    for _ in range(N):
        nopt = rng.randint(1, 3)
        group = [(0.0, 0.0)]
        for _ in range(nopt - 1):
            group.append((rng.uniform(0.5, 4.0), rng.uniform(0.1, 1.5)))
        options.append(group)
    nb = rng.randint(4, 8)
    nz = rng.randint(4, 8)
    budgets = sorted(rng.uniform(0.0, 8.0) for _ in range(nb))
    # strict budgets
    budgets = [b * (1 + 0.3 * i) for i, b in enumerate(budgets)]
    L = rng.randint(1, 3)
    weight_sets = [[rng.uniform(0.0, 3.0) for _ in range(K)] for _ in range(L)]
    zs = sorted(rng.uniform(0.0, 3.0) * (1 + 0.2 * i) for i in range(nz))
    return (H, W, thresholds, quantiles, policies, options, budgets, weight_sets, zs)


stats = {"branches": 0, "changes": 0, "consistent": 0, "conflicts": 0, "cases": 0}
for seed in range(300):
    args = make_case(seed)
    try:
        J = robust_policy_joint(*args)
    except ValueError:
        continue
    stats["cases"] += 1
    L = robust_policy_lineage(*args)
    S = robust_policy_change_summary(*args)
    oracle(args, S, J, L)
    stats["branches"] += len(J["branches"])
    stats["changes"] += len(J["adjacency_changes"])
    stats["consistent"] += len(S["consistent"])
    stats["conflicts"] += len(S["conflicts"])
    if J["branches"] and J["adjacency_changes"]:
        assert S["regions"]
        assert S == robust_policy_change_summary(*args)

print(stats)
assert stats["branches"] > 0 and stats["changes"] > 0
assert stats["consistent"] > 0 or stats["conflicts"] > 0
